function page_muscle_map(array $u):void
{
  require_role('professional');$pid=professional_id($u);$selected=(string)($_GET['muscle']??'');
  $muscles=[
    'peitoral'=>['Peitoral',['Peitoral']], 'costas'=>['Costas',['Costas']], 'ombros'=>['Ombros',['Ombros']],
    'biceps'=>['Bíceps',['Bíceps']], 'triceps'=>['Tríceps',['Tríceps']], 'abdomen'=>['Abdômen',['Abdômen']],
    'gluteos'=>['Glúteos',['Glúteos','glúteo']], 'quadriceps'=>['Quadríceps',['Quadríceps']],
    'posterior'=>['Posterior de coxa',['Posterior']], 'panturrilhas'=>['Panturrilhas',['Panturrilha']],
  ];
  if($selected!==''&&!isset($muscles[$selected]))$selected='';$rows=[];
  if($selected!==''){$terms=$muscles[$selected][1];$conditions=[];$args=[];foreach($terms as $term){$conditions[]='muscle_group LIKE ?';$args[]='%'.$term.'%';}$stmt=db()->prepare('SELECT * FROM global_exercises WHERE active=1 AND ('.implode(' OR ',$conditions).') ORDER BY name');$stmt->execute($args);$rows=$stmt->fetchAll();}
