function page_exercises_v2(array $u):void
{
  require_role(['admin','professional']);
  $profs=[];
  if($u['role']==='admin'){
    $pq=db()->prepare('SELECT p.id,u.name FROM professionals p JOIN users u ON u.id=p.user_id WHERE p.tenant_id=? ORDER BY u.name');
    $pq->execute([$u['tenant_id']]);$profs=$pq->fetchAll();$pid=(int)($_GET['prof']??($profs[0]['id']??0));
  }else{$pid=professional_id($u);}
  $stmt=db()->prepare('SELECT * FROM exercise_catalog WHERE professional_id=? AND active=1 ORDER BY name');$stmt->execute([$pid]);$rows=$stmt->fetchAll();
  $global=db()->query('SELECT * FROM global_exercises WHERE active=1 ORDER BY muscle_group,name')->fetchAll();
  $groups=array_values(array_unique(array_filter(array_column($global,'muscle_group'))));sort($groups);
  $editId=(int)($_GET['edit']??0);$edit=null;foreach($rows as $r)if((int)$r['id']===$editId)$edit=$r;
  ?>
  <?php if($u['role']==='admin'):?><div class="notice admin-boundary">O administrador gerencia o banco de exercícios, mas não acessa prontuários ou fichas de alunos.</div><form class="filter-bar" method="get"><input type="hidden" name="page" value="exercises"><label>Visualizar catálogo do profissional<select name="prof" onchange="this.form.submit()"><?php foreach($profs as $p):?><option <?=$pid===$p['id']?'selected':''?> value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label></form><?php endif;?>
  <section class="panel catalog-panel"><div class="panel-head"><div><p class="eyebrow">BIBLIOTECA PRONTA</p><h2>Encontre e adicione exercícios</h2><p>Pesquise pelo nome ou escolha um grupo muscular.</p></div><span class="pill"><?=count($global)?> disponíveis</span></div>
    <div class="catalog-tools"><label><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg></span><input id="exerciseSearch" type="search" placeholder="Buscar exercício, equipamento..."></label><select id="exerciseGroup"><option value="">Todos os grupos musculares</option><?php foreach($groups as $group):?><option value="<?=e($group)?>"><?=e($group)?></option><?php endforeach;?></select></div>
    <div class="catalog-select-grid" id="exerciseGrid"><?php foreach($global as $g):?><article data-name="<?=e($g['name'].' '.$g['equipment'])?>" data-group="<?=e($g['muscle_group'])?>"><div class="catalog-thumb"><span class="figure prepare">●<i></i></span><span class="figure active">●<i></i></span><small><?=e($g['muscle_group'])?></small></div><div class="catalog-card-body"><small><?=e($g['equipment']?:'Sem equipamento')?></small><h3><?=e($g['name'])?></h3><p><?=e($g['instructions'])?></p><details><summary>Ver como executar</summary><div class="mini-steps"><span><b>1</b>Prepare</span><span><b>2</b>Execute</span><span><b>3</b>Retorne</span></div></details><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="copy_global_exercise"><input type="hidden" name="global_exercise_id" value="<?=$g['id']?>"><input type="hidden" name="professional_id" value="<?=$pid?>"><button class="primary">+ Adicionar ao meu catálogo</button></form></div></article><?php endforeach;?></div>
  </section>
  <div class="two-col wide-main"><section class="panel"><div class="panel-head"><div><h2>Meu catálogo</h2><p>Exercícios que você já selecionou e pode personalizar.</p></div><span class="pill"><?=count($rows)?> itens</span></div><div class="my-exercise-list"><?php if(!$rows):?><div class="empty">Adicione exercícios da biblioteca acima.</div><?php endif;foreach($rows as $r):?><article><?php if($r['image_path']):?><img src="<?=e($r['image_path'])?>" alt="<?=e($r['name'])?>"><?php else:?><div class="exercise-motion"><span>●</span><i></i><small>Sem foto</small></div><?php endif;?><div><small><?=e($r['muscle_group']?:'Grupo muscular')?></small><h3><?=e($r['name'])?></h3><p><?=e($r['instructions']?:'Adicione as orientações de execução.')?></p><div class="actions"><a class="secondary button" href="<?=url('exercises',['edit'=>$r['id'],'prof'=>$pid])?>">Editar e adicionar foto</a><form method="post" onsubmit="return confirm('Excluir este exercício?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_exercise"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="professional_id" value="<?=$pid?>"><button class="danger">Excluir</button></form></div></div></article><?php endforeach;?></div></section>
    <section class="panel sticky exercise-editor"><p class="eyebrow">PERSONALIZAÇÃO</p><h2><?=$edit?'Editar exercício':'Cadastrar exercício próprio'?></h2><p>A foto e o vídeo serão mostrados ao aluno durante o treino.</p><form method="post" enctype="multipart/form-data" class="stack compact"><?=csrf_field()?><input type="hidden" name="action" value="save_exercise"><input type="hidden" name="id" value="<?=$editId?>"><input type="hidden" name="professional_id" value="<?=$pid?>"><label>Nome<input required name="name" value="<?=e($edit['name']??'')?>"></label><label>Grupo muscular<input name="muscle_group" value="<?=e($edit['muscle_group']??'')?>"></label><label>Equipamento<input name="equipment" value="<?=e($edit['equipment']??'')?>"></label><label>Explicação para o aluno<textarea name="instructions" rows="5"><?=e($edit['instructions']??'')?></textarea></label><label>Foto demonstrativa<input type="file" accept="image/jpeg,image/png,image/webp" name="image"></label><label>Link do vídeo<input type="url" name="video_url" value="<?=e($edit['video_url']??'')?>"></label><button class="primary">Salvar exercício</button></form></section></div>
  <script>const search=document.getElementById('exerciseSearch'),group=document.getElementById('exerciseGroup'),cards=[...document.querySelectorAll('#exerciseGrid>article')];function filterExercises(){const q=(search.value||'').toLocaleLowerCase('pt-BR'),g=group.value;cards.forEach(c=>c.hidden=!(c.dataset.name.toLocaleLowerCase('pt-BR').includes(q)&&(!g||c.dataset.group===g)))}search.addEventListener('input',filterExercises);group.addEventListener('change',filterExercises);</script>
  <?php
}

function page_session_v2(array $u):void
{
  require_role('student');$id=(int)($_GET['id']??0);
  $stmt=db()->prepare('SELECT wsess.*,ws.name FROM workout_sessions wsess JOIN workout_sheets ws ON ws.id=wsess.workout_sheet_id JOIN students s ON s.id=wsess.student_id WHERE wsess.id=? AND s.user_id=?');$stmt->execute([$id,$u['id']]);$session=$stmt->fetch();if(!$session){page_not_found();return;}
  $q=db()->prepare('SELECT wi.*,e.name,e.instructions,e.image_path,e.video_url,e.muscle_group FROM workout_items wi JOIN exercise_catalog e ON e.id=wi.exercise_id WHERE wi.workout_sheet_id=? ORDER BY wi.sort_order,wi.id');$q->execute([$session['workout_sheet_id']]);$items=$q->fetchAll();
  ?><section class="session-hero"><div><p class="eyebrow">TREINO EM ANDAMENTO</p><h2><?=e($session['name'])?></h2><p><?=count($items)?> exercícios preparados pelo seu profissional</p></div><div class="timer" data-start="<?=strtotime($session['started_at'])?>">00:00</div></section>
  <div class="guided-workout"><?php foreach($items as $i=>$it):?><article class="guided-exercise"><div class="exercise-media"><?php if($it['image_path']):?><img src="<?=e($it['image_path'])?>" alt="Demonstração de <?=e($it['name'])?>"><?php else:?><div class="movement-demo"><div><span class="movement-number">1</span><b>Prepare</b><small>Posicione-se com segurança</small></div><i>→</i><div class="main"><span class="movement-number">2</span><b>Execute</b><small>Faça o movimento controlado</small></div><i>→</i><div><span class="movement-number">3</span><b>Retorne</b><small>Volte à posição inicial</small></div></div><?php endif;?></div><div class="exercise-info"><span class="step-label">EXERCÍCIO <?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?> · <?=e($it['muscle_group'])?></span><h2><?=e($it['name'])?></h2><div class="exercise-prescription"><span><small>Séries</small><b><?=$it['sets_count']?></b></span><span><small>Repetições</small><b><?=e($it['repetitions'])?></b></span><span><small>Carga</small><b><?=e($it['suggested_load']?:'Livre')?></b></span><span><small>Descanso</small><b><?=$it['rest_seconds']?>s</b></span></div><div class="execution-tip"><b>Como executar</b><p><?=e($it['instructions']?:'Siga a orientação do seu profissional e faça o movimento de forma controlada.')?></p></div><?php if($it['video_url']):?><a class="video-button" target="_blank" rel="noopener" href="<?=e($it['video_url'])?>">Assistir demonstração em vídeo</a><?php endif;?></div></article><?php endforeach;?></div>
  <form method="post" class="finish-box"><?=csrf_field()?><input type="hidden" name="action" value="finish_workout"><input type="hidden" name="session_id" value="<?=$id?>"><label>Como foi o treino?<textarea name="notes" placeholder="Conte sobre cargas, dificuldade ou desconfortos..."></textarea></label><button class="primary">Finalizar treino</button></form><script>const t=document.querySelector('.timer');setInterval(()=>{const d=Math.max(0,Math.floor(Date.now()/1000-Number(t.dataset.start)));t.textContent=String(Math.floor(d/60)).padStart(2,'0')+':'+String(d%60).padStart(2,'0')},1000)</script><?php
}

function page_session_v3(array $u):void
{
  require_role('student');$id=(int)($_GET['id']??0);
  $stmt=db()->prepare('SELECT wsess.*,ws.name FROM workout_sessions wsess JOIN workout_sheets ws ON ws.id=wsess.workout_sheet_id JOIN students s ON s.id=wsess.student_id WHERE wsess.id=? AND s.user_id=?');$stmt->execute([$id,$u['id']]);$session=$stmt->fetch();if(!$session){page_not_found();return;}
  $columnCheck=db()->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='workout_logs' AND COLUMN_NAME IN ('started_at','completed_at')");
  if((int)$columnCheck->fetchColumn()<2){echo '<div class="notice"><b>Atualização do treino pendente.</b><p>O administrador precisa importar o arquivo database/migrations/003_tempo_por_exercicio.sql. Enquanto isso, a execução básica continua disponível.</p></div>';page_session_v2($u);return;}
  $pauseCheck=db()->query("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='workout_sessions' AND COLUMN_NAME IN ('timer_started_at','paused_at','paused_seconds')");$timerReady=(int)$pauseCheck->fetchColumn()===3;$timerStarted=$timerReady?($session['timer_started_at']??null):$session['started_at'];$sessionState=!$timerStarted?'waiting':(($session['paused_at']??null)?'paused':'running');
  $q=db()->prepare('SELECT wi.*,e.name,e.instructions,e.image_path,e.video_url,e.muscle_group,wl.started_at exercise_started_at,wl.completed_at exercise_completed_at,wl.completed FROM workout_items wi JOIN exercise_catalog e ON e.id=wi.exercise_id LEFT JOIN workout_logs wl ON wl.workout_item_id=wi.id AND wl.session_id=? WHERE wi.workout_sheet_id=? ORDER BY wi.sort_order,wi.id');$q->execute([$id,$session['workout_sheet_id']]);$items=$q->fetchAll();$completed=count(array_filter($items,fn($item)=>(int)$item['completed']===1));
  ?><div class="session-brand"><?php if($u['logo_path']):?><img src="<?=e($u['logo_path'])?>" alt="Logo <?=e($u['tenant_name'])?>"><?php else:?><img src="assets/images/logo-kinsman.png" alt="Logo Kinsman"><?php endif;?><div><strong><?=e($u['tenant_name'])?></strong><small>Treino acompanhado</small></div></div><?php if(!$timerReady):?><div class="notice"><b>Novo cronômetro pendente.</b><p>Importe a atualização <code>database/migrations/006_anamnese_e_inicio_do_treino.sql</code> para iniciar o tempo somente quando você apertar o botão.</p></div><?php endif;?><section class="session-hero <?=$sessionState==='paused'?'is-paused':''?> <?=$sessionState==='waiting'?'is-waiting':''?>" id="sessionHero"><div><p class="eyebrow" id="sessionState"><?=['waiting'=>'TREINO PRONTO PARA COMEÇAR','paused'=>'TREINO PAUSADO','running'=>'TREINO EM ANDAMENTO'][$sessionState]?></p><h2><?=e($session['name'])?></h2><p><strong id="completedCount"><?=$completed?></strong> de <?=count($items)?> exercícios concluídos</p></div><div class="session-clock"><div class="timer" data-start="<?=$timerStarted?strtotime($timerStarted):''?>" data-paused-seconds="<?=(int)($session['paused_seconds']??0)?>" data-paused-at="<?=($session['paused_at']??null)?strtotime($session['paused_at']):''?>">00:00</div><?php if($timerReady):?><button type="button" class="pause-workout" id="controlWorkout" data-session="<?=$id?>" data-command="<?=$sessionState==='waiting'?'start':($sessionState==='paused'?'resume':'pause')?>"><?=$sessionState==='waiting'?'Inicializar':($sessionState==='paused'?'Continuar':'Pausar')?></button><?php endif;?></div></section>
  <div class="exercise-progress"><i style="width:<?=count($items)?round($completed/count($items)*100):0?>%"></i></div>
  <div class="check-workout" id="checkWorkout"><?php foreach($items as $i=>$it):$done=(int)$it['completed']===1;?><details class="exercise-check-card <?=$done?'done':''?>" data-session="<?=$id?>" data-item="<?=$it['id']?>" <?=$it['exercise_started_at']&&!$done?'open':''?>><summary><span class="exercise-order"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><div><small><?=e($it['muscle_group'])?></small><h3><?=e($it['name'])?></h3><p><?=$it['sets_count']?> séries · <?=e($it['repetitions'])?> repetições · <?=e($it['suggested_load']?:'Carga livre')?></p></div><label class="done-check" onclick="event.stopPropagation()"><input type="checkbox" <?=$done?'checked':''?> aria-label="Marcar <?=e($it['name'])?> como concluído"><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 4 4L19 6"/></svg></span><b><?=$done?'Concluído':'Marcar feito'?></b></label><span class="open-hint">Ver execução⌄</span></summary><div class="exercise-check-content"><div class="exercise-media"><?php if($it['image_path']):?><img src="<?=e($it['image_path'])?>" alt="Demonstração de <?=e($it['name'])?>"><?php else:?><div class="movement-demo"><div><span class="movement-number">1</span><b>Prepare</b><small>Posicione-se com segurança</small></div><i>→</i><div class="main"><span class="movement-number">2</span><b>Execute</b><small>Faça o movimento controlado</small></div><i>→</i><div><span class="movement-number">3</span><b>Retorne</b><small>Volte à posição inicial</small></div></div><?php endif;?></div><div class="exercise-info"><div class="exercise-prescription"><span><small>Séries</small><b><?=$it['sets_count']?></b></span><span><small>Repetições</small><b><?=e($it['repetitions'])?></b></span><span><small>Carga</small><b><?=e($it['suggested_load']?:'Livre')?></b></span><span><small>Descanso</small><b><?=$it['rest_seconds']?>s</b></span></div><div class="execution-tip"><b>Como executar</b><p><?=e($it['instructions']?:'Siga a orientação do profissional e execute o movimento com controle.')?></p></div><?php if($it['video_url']):?><a class="video-button" target="_blank" rel="noopener" href="<?=e($it['video_url'])?>">Assistir demonstração</a><?php endif;?><div class="exercise-times"><span>Início: <b class="started-time"><?=$it['exercise_started_at']?date('H:i',strtotime($it['exercise_started_at'])):'—'?></b></span><span>Fim: <b class="completed-time"><?=$it['exercise_completed_at']?date('H:i',strtotime($it['exercise_completed_at'])):'—'?></b></span></div></div></div></details><?php endforeach;?></div>
  <form method="post" class="finish-box" onsubmit="return confirm('Deseja finalizar o treino completo? O próximo treino começará novamente em 00:00.')"><?=csrf_field()?><input type="hidden" name="action" value="finish_workout"><input type="hidden" name="session_id" value="<?=$id?>"><label>Como foi o treino?<textarea name="notes" placeholder="Conte sobre cargas, dificuldade ou desconfortos..."></textarea></label><button class="primary" id="finishWorkout" <?=$sessionState==='waiting'?'disabled':''?>>Finalizar treino completo</button></form>
  <script>const csrf=<?=json_encode(csrf_token())?>,endpoint='index.php',total=<?=count($items)?>;let workoutState=<?=json_encode($sessionState)?>;async function postWorkout(data){const body=new URLSearchParams({csrf,...data}),response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!response.ok)throw new Error('Falha ao salvar');const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('Resposta inválida');return response.json()}async function saveExercise(card,state){return postWorkout({action:'update_workout_exercise',session_id:card.dataset.session,workout_item_id:card.dataset.item,state})}document.querySelectorAll('.exercise-check-card').forEach(card=>{card.addEventListener('toggle',async()=>{if(card.open&&card.querySelector('.started-time').textContent==='—'&&workoutState==='running'){try{const data=await saveExercise(card,'started');card.querySelector('.started-time').textContent=data.time}catch(e){}}});const input=card.querySelector('.done-check input');input.addEventListener('change',async()=>{if(workoutState!=='running'){input.checked=false;alert(workoutState==='waiting'?'Inicialize o treino antes de marcar o exercício.':'Continue o treino antes de marcar o exercício.');return}if(!input.checked){input.checked=true;return}input.disabled=true;try{const data=await saveExercise(card,'completed');card.classList.add('done');card.querySelector('.done-check b').textContent='Concluído';card.querySelector('.started-time').textContent=card.querySelector('.started-time').textContent==='—'?data.time:card.querySelector('.started-time').textContent;card.querySelector('.completed-time').textContent=data.time;const count=document.querySelectorAll('.exercise-check-card.done').length;document.getElementById('completedCount').textContent=count;document.querySelector('.exercise-progress i').style.width=(total?count/total*100:0)+'%';setTimeout(()=>card.open=false,450)}catch(e){input.checked=false;input.disabled=false;alert('Não foi possível salvar. Tente novamente.')}})});const timer=document.querySelector('.timer'),controlButton=document.getElementById('controlWorkout'),finishButton=document.getElementById('finishWorkout'),hero=document.getElementById('sessionHero'),stateLabel=document.getElementById('sessionState');let pausedSeconds=Number(timer.dataset.pausedSeconds||0),pausedAt=Number(timer.dataset.pausedAt||0),timerStarted=Number(timer.dataset.start||0);function renderTimer(){if(!timerStarted){timer.textContent='00:00';return}const now=Math.floor(Date.now()/1000),currentPause=workoutState==='paused'&&pausedAt?now-pausedAt:0,d=Math.max(0,now-timerStarted-pausedSeconds-currentPause);timer.textContent=String(Math.floor(d/60)).padStart(2,'0')+':'+String(d%60).padStart(2,'0')}renderTimer();setInterval(renderTimer,1000);controlButton?.addEventListener('click',async()=>{controlButton.disabled=true;try{const previous=workoutState,command=controlButton.dataset.command,data=await postWorkout({action:'control_workout',session_id:controlButton.dataset.session,command});workoutState=data.state;if(command==='start'){timerStarted=data.server_time;pausedSeconds=0;pausedAt=0;finishButton.disabled=false}else if(workoutState==='paused'){pausedAt=data.server_time}else{if(previous==='paused'&&pausedAt)pausedSeconds+=Math.max(0,data.server_time-pausedAt);pausedAt=0}if(workoutState==='paused'){controlButton.textContent='Continuar';controlButton.dataset.command='resume';stateLabel.textContent='TREINO PAUSADO';hero.classList.add('is-paused')}else{controlButton.textContent='Pausar';controlButton.dataset.command='pause';stateLabel.textContent='TREINO EM ANDAMENTO';hero.classList.remove('is-paused','is-waiting')}renderTimer()}catch(e){alert('Não foi possível alterar o cronômetro. Atualize a página e tente novamente.')}finally{controlButton.disabled=false}})</script><?php
}

