function page_my_progress(array $u):void
{
  require_role('student');$s=student_for_user($u);$q=db()->prepare('SELECT * FROM assessments WHERE student_id=? ORDER BY assessed_at DESC LIMIT 20');$q->execute([$s['id']]);$assessments=$q->fetchAll();$latest=$assessments[0]??null;$first=$assessments?end($assessments):null;$q=db()->prepare('SELECT pp.*,a.assessed_at FROM progress_photos pp JOIN assessments a ON a.id=pp.assessment_id WHERE pp.student_id=? ORDER BY a.assessed_at DESC,pp.id DESC LIMIT 12');$q->execute([$s['id']]);$photos=$q->fetchAll();$nextDate=$latest?strtotime($latest['assessed_at'].' +30 days'):strtotime('+30 days');
  ?><div class="progress-head"><div><p class="eyebrow">MEU ACOMPANHAMENTO</p><h1>Minha evolução</h1><p>Registre seu progresso e acompanhe cada conquista.</p></div><details class="progress-add"><summary class="primary button">+ Adicionar registro</summary><form method="post" enctype="multipart/form-data" class="progress-popover stack"><?=csrf_field()?><input type="hidden" name="action" value="update_weight"><h2>Novo registro</h2><div class="fields-2"><label>Peso atual (kg)<input required type="number" min="20" max="400" step=".01" name="weight_kg" value="<?=e((string)$s['current_weight_kg'])?>"></label><label>Cintura (cm)<input type="number" min="20" max="300" step=".01" name="waist_cm"></label><label>Quadril (cm)<input type="number" min="20" max="300" step=".01" name="hip_cm"></label></div><label>Observação<textarea name="notes" placeholder="Como você está se sentindo?"></textarea></label><div class="photo-inputs"><label>Foto de frente<input type="file" accept="image/jpeg,image/png,image/webp" name="progress_front"></label><label>Foto lateral<input type="file" accept="image/jpeg,image/png,image/webp" name="progress_side"></label><label>Foto de costas<input type="file" accept="image/jpeg,image/png,image/webp" name="progress_back"></label></div><small>As fotos são privadas: somente você e seu profissional podem visualizar.</small><button class="primary">Salvar evolução</button></form></details></div>
  <div class="progress-metrics"><article><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8a5 5 0 0 1 8 0M12 8l2-2"/></svg></span><div><small>Peso atual</small><strong><?=number_format((float)$s['current_weight_kg'],1,',','.')?> kg</strong><em><?=($first&&$first['weight_kg']!==null?number_format((float)$s['current_weight_kg']-(float)$first['weight_kg'],1,',','.').' kg desde o início':'Primeiro registro')?></em></div></article><article><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m4 18 6-6 4 3 6-10M14 5h6v6"/></svg></span><div><small>Cintura</small><strong><?=$latest&&$latest['waist_cm']!==null?number_format((float)$latest['waist_cm'],1,',','.').' cm':'—'?></strong><em>Acompanhamento de medidas</em></div></article><article><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg></span><div><small>Próxima avaliação</small><strong><?=date('d/m',$nextDate)?></strong><em>Em <?=max(0,(int)ceil(($nextDate-time())/86400))?> dias</em></div></article></div>
  <section class="panel progress-photos"><div class="panel-head"><div><h2>Fotos de evolução</h2><p>Privadas: somente você e seu profissional podem visualizar.</p></div></div><div class="photo-grid"><?php if(!$photos):?><div class="empty"><b>Seu registro visual começa aqui</b><p>Adicione fotos frontal, lateral e posterior no botão “Adicionar registro”.</p></div><?php endif;?><?php foreach($photos as $photo):?><figure><img src="<?=e($photo['image_path'])?>" alt="Foto de evolução"><figcaption><b><?=e(['front'=>'Frente','side'=>'Lateral','back'=>'Posterior','other'=>'Outra'][$photo['photo_type']]??'Evolução')?></b><small><?=date('d/m/Y',strtotime($photo['assessed_at']))?></small></figcaption></figure><?php endforeach;?></div></section>
  <section class="panel progress-history"><h2>Histórico de medidas</h2><p>Últimos registros realizados.</p><div class="measure-table"><?php if(!$assessments):?><div class="empty">Nenhum registro de evolução ainda.</div><?php endif;?><?php foreach($assessments as $a):?><article><b><?=date('d/m/Y',strtotime($a['assessed_at']))?></b><span><small>Peso</small><?=($a['weight_kg']!==null?number_format((float)$a['weight_kg'],1,',','.').' kg':'—')?></span><span><small>Cintura</small><?=($a['waist_cm']!==null?number_format((float)$a['waist_cm'],1,',','.').' cm':'—')?></span><span><small>Quadril</small><?=($a['hip_cm']!==null?number_format((float)$a['hip_cm'],1,',','.').' cm':'—')?></span></article><?php endforeach;?></div></section><?php
}
function page_session(array $u):void{require_role('student');$id=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT wsess.*,ws.name FROM workout_sessions wsess JOIN workout_sheets ws ON ws.id=wsess.workout_sheet_id JOIN students s ON s.id=wsess.student_id WHERE wsess.id=? AND s.user_id=?');$stmt->execute([$id,$u['id']]);$s=$stmt->fetch();if(!$s){page_not_found();return;}$q=db()->prepare('SELECT wi.*,e.name,e.instructions,e.image_path,e.video_url FROM workout_items wi JOIN exercise_catalog e ON e.id=wi.exercise_id WHERE wi.workout_sheet_id=? ORDER BY wi.sort_order,wi.id');$q->execute([$s['workout_sheet_id']]);?><section class="session-hero"><div><p class="eyebrow">TREINO EM ANDAMENTO</p><h2><?=e($s['name'])?></h2></div><div class="timer" data-start="<?=strtotime($s['started_at'])?>">00:00</div></section><div class="workout-session"><?php foreach($q->fetchAll() as $i=>$it):?><article><span class="number"><?=$i+1?></span><?php if($it['image_path']):?><img src="<?=e($it['image_path'])?>" alt="Demonstração de <?=e($it['name'])?>"><?php endif;?><div><h3><?=e($it['name'])?></h3><p><b><?=$it['sets_count']?> × <?=e($it['repetitions'])?></b> · descanso <?=$it['rest_seconds']?>s · carga <?=e($it['suggested_load'])?></p><p><?=e($it['instructions'])?></p><?php if($it['video_url']):?><a target="_blank" rel="noopener" href="<?=e($it['video_url'])?>">Ver demonstração em vídeo ↗</a><?php endif;?></div></article><?php endforeach;?></div><form method="post" class="finish-box"><?=csrf_field()?><input type="hidden" name="action" value="finish_workout"><input type="hidden" name="session_id" value="<?=$id?>"><label>Anotações do treino<textarea name="notes" placeholder="Carga, dificuldade, dores ou observações..."></textarea></label><button class="primary">Finalizar treino</button></form><script>const t=document.querySelector('.timer');setInterval(()=>{const d=Math.max(0,Math.floor(Date.now()/1000-Number(t.dataset.start)));t.textContent=String(Math.floor(d/60)).padStart(2,'0')+':'+String(d%60).padStart(2,'0')},1000)</script><?php }
function page_branding(array $u):void{require_role(['admin','professional']);?><div class="two-col"><section class="panel"><h2>Identidade visual</h2><p>Personalize a experiência dos seus alunos sem alterar a estrutura do Pulse.</p><form method="post" enctype="multipart/form-data" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="save_brand"><label>Nome da marca<input required name="name" value="<?=e($u['tenant_name'])?>"></label><label>Logo JPG, PNG ou WebP<input type="file" accept="image/jpeg,image/png,image/webp" name="logo"></label><label>Cor principal<input type="color" name="primary_color" value="<?=e($u['primary_color'])?>"></label><?php if($u['role']==='professional'):?><label>WhatsApp<input name="whatsapp" placeholder="5531999999999" value="<?=e($u['brand_whatsapp'])?>"></label><label>Instagram<input name="instagram" placeholder="@suamarca" value="<?=e($u['brand_instagram'])?>"></label><label>Mensagem para o aluno<input maxlength="255" name="welcome_message" value="<?=e($u['welcome_message'])?>"></label><label>Texto do rodapé<input maxlength="180" name="footer_text" value="<?=e($u['footer_text'])?>"></label><?php endif;?><button class="primary">Salvar identidade</button></form></section><section class="brand-preview" style="--brand:<?=e($u['primary_color'])?>"><?php if($u['logo_path']):?><img src="<?=e($u['logo_path'])?>" alt="Logo atual"><?php else:?><img class="official-logo" src="assets/images/logo-kinsman.png" alt="Logo Kinsman"><?php endif;?><h2><?=e($u['tenant_name'])?></h2><p><?=e($u['welcome_message']?:'Acompanhamento com a identidade do profissional.')?></p><button>Botão principal</button></section></div><?php }
function page_finance(array $u):void{
  if($u['role']==='professional'){
    $pid=professional_id($u);
    $q=db()->prepare('SELECT subscription_plan,subscription_status,service_type,trial_ends_at,access_until,referral_code FROM professionals WHERE id=?');$q->execute([$pid]);$subscription=$q->fetch();
    $limit=subscription_limit($subscription['subscription_plan']);
    $q=db()->prepare('SELECT COUNT(*) FROM students s JOIN users us ON us.id=s.user_id WHERE s.professional_id=? AND us.active=1');$q->execute([$pid]);$students=(int)$q->fetchColumn();
    $q=db()->prepare("SELECT status,COUNT(*) total FROM referral_rewards WHERE referrer_professional_id=? GROUP BY status");$q->execute([$pid]);$rewards=[];foreach($q->fetchAll() as $reward)$rewards[$reward['status']]=(int)$reward['total'];
    $price=subscription_price($subscription['subscription_plan'],$subscription['service_type']);$single=$subscription['service_type']!=='complete';
    $statusLabels=['trial'=>'Teste grátis','active'=>'Ativo','past_due'=>'Em atraso','cancelled'=>'Cancelado'];$statusLabel=$statusLabels[$subscription['subscription_status']]??'Aguardando pagamento';?>
    <section class="panel"><div class="panel-head"><div><h2>Minha assinatura Pulse</h2><p><?=e($single?($subscription['service_type']==='nutrition'?'Modalidade Nutricionista':'Modalidade Personal trainer'):'Modalidade completa: Personal + Nutrição')?>.</p></div><span class="status <?=in_array($subscription['subscription_status'],['trial','active'],true)?'published':'draft'?>"><?=e($statusLabel)?></span></div>
    <?php if($subscription['subscription_status']==='trial'&&!empty($subscription['trial_ends_at'])):?><div class="notice"><b>Seu teste grátis está ativo até <?=date('d/m/Y',strtotime($subscription['trial_ends_at']))?>.</b><p>Você pode usar todos os recursos profissionais durante esse período. Não há cobrança automática.</p></div><?php elseif($subscription['subscription_status']==='past_due'&&!empty($subscription['access_until'])):?><div class="notice">Pagamento em atraso. Você pode regularizar até <?=date('d/m/Y',strtotime($subscription['access_until']))?>. Depois dessa data, os recursos ficarão inativos até a confirmação do pagamento pela Asaas.</div><?php elseif($subscription['subscription_status']!=='active'):?><div class="notice">Seu teste terminou. Escolha um plano para continuar usando o Pulse.</div><?php endif;?>
    <?php if(($_GET['checkout']??'')==='success'):?><div class="notice">Pagamento enviado. A ativação ocorrerá automaticamente após a confirmação da Asaas.</div><?php endif;?>
    <div class="metric-grid"><article class="metric"><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/></svg></span><small>Plano</small><strong><?=e(ucfirst($subscription['subscription_plan']))?></strong></article><article class="metric"><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/></svg></span><small>Alunos ativos</small><strong><?=$students?> / <?=$limit?></strong></article><article class="metric"><span><svg class="ui-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20M17 5H9a3.5 3.5 0 0 0 0 7h6a3.5 3.5 0 0 1 0 7H6"/></svg></span><small>Mensalidade</small><strong>R$ <?=number_format($price/100,2,',','.')?></strong></article></div>
    <div class="plan-cards"><?php foreach([['basic','Basic',20],['plus','Plus',40],['premium','Premium',100]] as [$code,$name,$cap]):$planPrice=subscription_price($code,$subscription['service_type']);?><article><b><?=$name?></b><strong>R$ <?=number_format($planPrice/100,2,',','.')?></strong><span>até <?=$cap?> alunos ativos</span><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="start_asaas_checkout"><input type="hidden" name="plan" value="<?=$code?>"><button class="primary" <?=!asaas_enabled()?'disabled':''?>>Assinar com Asaas</button></form></article><?php endforeach;?></div>
    <section class="referral-card"><div><small>INDIQUE E GANHE</small><h3>Uma mensalidade grátis por indicação aprovada</h3><p>Compartilhe seu link. O crédito fica disponível quando o indicado pagar a primeira mensalidade.</p></div><div><label>Seu link de indicação<input readonly value="<?=e(rtrim((string)env('APP_URL'),'/').'/index.php?page=register&ref='.$subscription['referral_code'])?>"></label><small><?=($rewards['available']??0)?> crédito(s) disponível(is) · <?=($rewards['pending']??0)?> pendente(s)</small></div></section>
    <?php if($subscription['subscription_status']==='active'):?><details class="cancel-box"><summary>Cancelar renovação</summary><p>Não serão geradas novas mensalidades. O acesso permanece até o fim do período já pago.</p><form method="post" onsubmit="return confirm('Confirma o cancelamento da renovação?')"><?=csrf_field()?><input type="hidden" name="action" value="cancel_subscription"><button class="danger">Confirmar cancelamento</button></form></details><?php elseif(!empty($subscription['access_until'])):?><div class="notice">Acesso disponível até <?=date('d/m/Y',strtotime($subscription['access_until']))?>.</div><?php endif;?>
    <p>Acima de 100 alunos, solicite um plano personalizado com a Kinsman.</p></section><?php return;
  }
  ?><section class="panel"><div class="panel-head"><div><h2>Financeiro</h2><p>Planos dos profissionais e situação das assinaturas.</p></div><span class="status published">Asaas integrado</span></div><div class="plan-cards"><article><b>Basic</b><strong>R$ 89,90</strong><span>até 20 alunos</span></article><article><b>Plus</b><strong>R$ 129,00</strong><span>até 40 alunos</span></article><article><b>Premium</b><strong>R$ 219,00</strong><span>até 100 alunos</span></article></div><div class="notice">Acima de 100 alunos, ofereça um plano personalizado.</div></section><?php
}
function page_workout(array $u):void
{
  require_role(['admin','professional']);
  $id=(int)($_GET['id']??0);
  $stmt=db()->prepare('SELECT ws.*,s.professional_id,u.name student_name FROM workout_sheets ws JOIN students s ON s.id=ws.student_id JOIN users u ON u.id=s.user_id WHERE ws.id=?');
  $stmt->execute([$id]);$w=$stmt->fetch();if(!$w){page_not_found();return;}get_scoped_student((int)$w['student_id'],$u);
  $q=db()->prepare('SELECT wi.*,e.name,e.instructions,e.image_path,e.muscle_group FROM workout_items wi JOIN exercise_catalog e ON e.id=wi.exercise_id WHERE wi.workout_sheet_id=? ORDER BY wi.sort_order,wi.id');$q->execute([$id]);$items=$q->fetchAll();
  $q=db()->prepare('SELECT * FROM exercise_catalog WHERE professional_id=? AND active=1 ORDER BY name');$q->execute([$w['professional_id']]);$catalog=$q->fetchAll();
  $editItem=(int)($_GET['edit_item']??0);$editing=null;foreach($items as $it)if((int)$it['id']===$editItem)$editing=$it;
  ?>
  <a class="back" href="<?=url('student',['id'=>$w['student_id'],'tab'=>'workouts'])?>">← Voltar às fichas</a>
  <a class="secondary button export-button" target="_blank" href="<?=url('export-workout',['id'=>$id,'print'=>1])?>"><span class="pdf-icon" aria-hidden="true">PDF</span>Exportar PDF</a>
  <section class="editor-head"><div><p class="eyebrow">EDIÇÃO DENTRO DO PRONTUÁRIO</p><h2><?=e($w['name'])?> — versão <?=$w['version']?></h2><p><?=e($w['objective'])?></p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="publish_workout"><input type="hidden" name="id" value="<?=$id?>"><button class="primary">Publicar para o aluno</button></form></section>
  <div class="two-col wide-main"><section class="panel"><h2>Exercícios da ficha</h2><div class="workout-list">
  <?php if(!$items):?><div class="empty">Adicione o primeiro exercício do catálogo.</div><?php endif;?>
  <?php foreach($items as $i=>$it):?><article><span class="number"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><?php if($it['image_path']):?><img src="<?=e($it['image_path'])?>" alt="<?=e($it['name'])?>"><?php endif;?><div><small><?=e($it['muscle_group'])?></small><h3><?=e($it['name'])?></h3><p><?=$it['sets_count']?> séries · <?=e($it['repetitions'])?> repetições · <?=e($it['suggested_load'])?> · descanso <?=$it['rest_seconds']?>s</p><em><?=e($it['notes'])?></em><div class="actions"><a class="mini-link" href="<?=url('student',['id'=>$w['student_id'],'tab'=>'workouts','edit_workout'=>$id,'edit_item'=>$it['id']])?>">Editar</a><form method="post" onsubmit="return confirm('Remover este exercício da ficha?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_workout_item"><input type="hidden" name="workout_sheet_id" value="<?=$id?>"><input type="hidden" name="item_id" value="<?=$it['id']?>"><button class="mini-danger">Remover</button></form></div></div></article><?php endforeach;?></div></section>
  <section class="panel sticky"><h2><?=$editing?'Editar exercício da ficha':'Inserir do catálogo'?></h2><form method="post" class="stack compact"><?=csrf_field()?><input type="hidden" name="action" value="save_workout_item"><input type="hidden" name="workout_sheet_id" value="<?=$id?>"><input type="hidden" name="item_id" value="<?=$editItem?>"><label>Exercício<select required name="exercise_id"><option value="">Selecione</option><?php foreach($catalog as $ex):?><option <?=($editing&&$editing['exercise_id']==$ex['id'])?'selected':''?> value="<?=$ex['id']?>"><?=e($ex['name'])?></option><?php endforeach;?></select></label><div class="fields-2"><label>Séries<input type="number" min="1" name="sets_count" value="<?=e((string)($editing['sets_count']??3))?>"></label><label>Repetições<input name="repetitions" value="<?=e((string)($editing['repetitions']??12))?>"></label><label>Carga sugerida<input name="suggested_load" value="<?=e($editing['suggested_load']??'')?>"></label><label>Descanso (s)<input type="number" min="0" name="rest_seconds" value="<?=e((string)($editing['rest_seconds']??60))?>"></label></div><label>Observações<textarea name="notes"><?=e($editing['notes']??'')?></textarea></label><input type="hidden" name="sort_order" value="<?=count($items)+1?>"><button class="primary"><?=$editing?'Salvar alteração':'Adicionar à ficha'?></button><?php if($editing):?><a class="secondary button" href="<?=url('student',['id'=>$w['student_id'],'tab'=>'workouts','edit_workout'=>$id])?>">Cancelar edição</a><?php endif;?></form></section></div>
  <?php
}
function page_not_found():void{http_response_code(404);echo'<section class="panel empty">Página não encontrada.</section>';}
